/* Native instruction composition, not a production loader/storage contract. */
#include "cold-page.h"
#include "bootstrap.h"

extern struct npu_barrier npu_emulation_barrier_state;
extern struct npu_admission npu_emulation_admission_state;
extern struct npu_bootstrap npu_emulation_bootstrap_state;
extern uint32_t npu_emulation_txdone_callback(const struct npu_bootstrap_packet *);
extern uint32_t npu_original_page_dispatch(uint32_t count, uint32_t selector);

struct npu_cold_page_state npu_emulation_page_state;
struct npu_cold_page_plan npu_emulation_page_plan;
struct npu_cold_page_queue_result npu_emulation_page_last;
static uint32_t busy;
static uint32_t arena_snapshot;

#define BARRIER (&npu_emulation_barrier_state)
#define ADMISSION (&npu_emulation_admission_state)
#define BOOT (&npu_emulation_bootstrap_state)
#define HEAD 0x3e903950u
#define TAIL 0x3e901f40u
#define POOL 0x3e8a9c70u

static uint32_t word(uint32_t address)
{
    return *(const volatile uint32_t *)(uintptr_t)address;
}

static uint32_t load(const uint32_t *address)
{
    return __atomic_load_n(address, __ATOMIC_ACQUIRE);
}

static int live(void)
{
    uint32_t i, stats = word(0x3e901f08u), arena = word(0x3e9030fcu);

    if (((uint32_t (*)(void))(uintptr_t)0x84004212u)() ||
        load(&BARRIER->request) != 1 || load(&BARRIER->fault) ||
        load(&BARRIER->prepared) || load(&BARRIER->released) || load(&BARRIER->armed) ||
        load(&ADMISSION->closed) != 1 || load(&ADMISSION->fault) ||
        load(&ADMISSION->active) != 1 || BOOT->magic != NPU_BOOTSTRAP_MAGIC ||
        BOOT->failed || BOOT->step != NPU_BOOTSTRAP_STEPS ||
        (arena & 31) || arena < 0x3e800000u || arena > 0x3e878000u - 303168u ||
        (arena_snapshot && arena_snapshot != arena) ||
        (stats && ((stats & 3) || stats < 0x3e800000u || stats > 0x3e878000u - 0x4c)) ||
        word(0x3e904634u) != POOL ||
        word(0x3e902ce4u) != BOOT->plan.region[NPU_BOOT_BA].base)
        return 0;
    for (i = 0; i < NPU_BARRIER_WORKERS; i++)
        if (load(&BARRIER->parked[i]) != 1)
            return 0;
    return 1;
}

static void statistic(uint32_t offset)
{
    uint32_t stats = word(0x3e901f08u);

    if (stats && !(stats & 3) && stats >= 0x3e800000u && stats <= 0x3e878000u - 0x4c) {
        volatile uint32_t *value = (volatile uint32_t *)(uintptr_t)(stats + offset);

        *value = *value + 1;
    }
}

static void fail(void)
{
    npu_cold_page_fault(&npu_emulation_page_state);
    npu_admission_fail(ADMISSION, BARRIER);
}

uint32_t npu_emulation_page_init(void)
{
    const struct npu_bootstrap_range *ba = &BOOT->plan.region[NPU_BOOT_BA];
    struct npu_cold_page_plan plan = {ba->base, ba->bytes};
    uint32_t status;

    if (!live() || *(const volatile uint16_t *)(uintptr_t)HEAD ||
        *(const volatile uint16_t *)(uintptr_t)TAIL)
        return NPU_COLD_PAGE_CORRUPT;
    status = npu_cold_page_init(&npu_emulation_page_state, &plan, 1);
    if (status == NPU_COLD_PAGE_OK || status == NPU_COLD_PAGE_FAULT) {
        npu_emulation_page_plan = plan;
        arena_snapshot = word(0x3e9030fcu);
    }
    return status;
}

uint32_t npu_emulation_page_get(void)
{
    const struct npu_cold_page_queue queue = {
        (volatile uint16_t *)(uintptr_t)HEAD,
        (const volatile uint16_t *)(uintptr_t)TAIL,
        (const volatile uint16_t *)(uintptr_t)POOL,
        NPU_COLD_PAGE_IDS
    };

    if (!busy || !live() || npu_emulation_page_plan.packet_base != BOOT->plan.region[NPU_BOOT_BA].base ||
        npu_emulation_page_plan.packet_bytes != BOOT->plan.region[NPU_BOOT_BA].bytes) {
        fail();
        return UINT32_MAX;
    }
    npu_emulation_page_last = npu_cold_page_queue_take(
        &npu_emulation_page_state, &npu_emulation_page_plan, 1, &queue);
    if (npu_emulation_page_last.page.status != NPU_COLD_PAGE_OK ||
        !npu_emulation_page_last.published || !live()) {
        statistic(0x44);
        fail();
        return UINT32_MAX;
    }
    statistic(0x48);
    return npu_emulation_page_last.page.id;
}

uint32_t npu_emulation_page_ready(void)
{
    if (!busy || !live() || load(&npu_emulation_page_state.fault)) {
        fail();
        return 0;
    }
    return 1;
}

uint32_t npu_emulation_page_callback(const struct npu_bootstrap_packet *packet)
{
    uint32_t selector = packet->header & 15, status, result = 0, ready;
    struct npu_bootstrap_packet snapshot;
    static const uint32_t limits[3] = {256, 512, 1024};
    static const uint32_t flags[3] = {0x3e901f44u, 0x3e903954u, 0x3e902ce8u};

    if (selector < 5 || selector > 7)
        return npu_emulation_txdone_callback(packet);
    __asm__ volatile ("csrrci %0, mstatus, 8" : "=r"(status) :: "memory");
    snapshot = *packet;
    ready = flags[selector - 5];
    if (snapshot.header != (0x10u | selector) || snapshot.api != 1 ||
        !snapshot.value || snapshot.value > limits[selector - 5] || busy ||
        !live() || word(ready) || load(&npu_emulation_page_state.fault) ||
        load(&npu_emulation_page_state.magic) != NPU_COLD_PAGE_MAGIC) {
        fail();
        goto done;
    }
    busy = 1;
    result = !npu_original_page_dispatch(snapshot.value, selector);
    if (!result || !live() || load(&npu_emulation_page_state.fault) || word(ready) != 1) {
        fail();
        *(volatile uint32_t *)(uintptr_t)ready = 0;
        result = 0;
    }
    busy = 0;
done:
    __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
    return result;
}

state.shared_core:
#include "cold-page.h"

_Static_assert(sizeof(struct npu_cold_page_state) == 1052, "cold page state changed");
_Static_assert(sizeof(struct npu_cold_page_plan) == 8, "cold page plan changed");
_Static_assert(sizeof(struct npu_cold_page_result) == 20, "cold page result changed");

static uint32_t faulted(const struct npu_cold_page_state *s)
{
    return __atomic_load_n(&s->fault, __ATOMIC_ACQUIRE);
}

void npu_cold_page_fault(struct npu_cold_page_state *s)
{
    if (s)
        __atomic_store_n(&s->fault, 1, __ATOMIC_RELEASE);
}

static int plan_valid(const struct npu_cold_page_plan *p)
{
    return p->packet_base >= 0x80000000u && p->packet_base < 0xc0000000u &&
           !(p->packet_base & (NPU_COLD_PAGE_BYTES - 1)) &&
           p->packet_bytes >= NPU_COLD_PAGE_IDS * NPU_COLD_PAGE_BYTES &&
           p->packet_bytes <= 0xc0000000u - p->packet_base;
}

static uint32_t population(uint32_t word)
{
    word -= (word >> 1) & 0x55555555u;
    word = (word & 0x33333333u) + ((word >> 2) & 0x33333333u);
    word = (word + (word >> 4)) & 0x0f0f0f0fu;
    return (word * 0x01010101u) >> 24;
}

uint32_t npu_cold_page_init(struct npu_cold_page_state *s,
                           const struct npu_cold_page_plan *p, uint32_t epoch)
{
    uint32_t i;

    if (!s || !p)
        return NPU_COLD_PAGE_ARGUMENT;
    if (s->magic || s->epoch || faulted(s) || s->head || s->count ||
        s->packet_base || s->packet_bytes)
        return NPU_COLD_PAGE_REINITIALIZE;
    for (i = 0; i < NPU_COLD_PAGE_WORDS; i++)
        if (s->claimed[i])
            return NPU_COLD_PAGE_REINITIALIZE;
    if (!epoch || !plan_valid(p)) {
        npu_cold_page_fault(s);
        return NPU_COLD_PAGE_PLAN;
    }
    s->epoch = epoch;
    s->packet_base = p->packet_base;
    s->packet_bytes = p->packet_bytes;
    __atomic_store_n(&s->magic, NPU_COLD_PAGE_MAGIC, __ATOMIC_RELEASE);
    return faulted(s) ? NPU_COLD_PAGE_FAULT : NPU_COLD_PAGE_OK;
}

static struct npu_cold_page_result fail(struct npu_cold_page_state *s, uint32_t status)
{
    struct npu_cold_page_result result = {status, UINT32_MAX, 0, UINT32_MAX, 0};

    npu_cold_page_fault(s);
    return result;
}

struct npu_cold_page_queue_result npu_cold_page_queue_take(
    struct npu_cold_page_state *s, const struct npu_cold_page_plan *p,
    uint32_t epoch, const struct npu_cold_page_queue *q)
{
    struct npu_cold_page_queue_result result;
    uint32_t head, tail, id;

    /* Field initialization avoids a -Os freestanding memcpy dependency. */
    result.page.status = NPU_COLD_PAGE_ARGUMENT;
    result.page.id = UINT32_MAX;
    result.page.address = 0;
    result.page.next_head = UINT32_MAX;
    result.page.committed = 0;
    result.published = 0;
    if (!s || !p || !q)
        return result;
    if (__atomic_load_n(&s->magic, __ATOMIC_ACQUIRE) != NPU_COLD_PAGE_MAGIC || faulted(s)) {
        result.page = fail(s, NPU_COLD_PAGE_FAULT);
        return result;
    }
    if (!s->epoch) {
        result.page = fail(s, NPU_COLD_PAGE_CORRUPT);
        return result;
    }
    if (!epoch || epoch != s->epoch) {
        result.page.status = NPU_COLD_PAGE_STALE;
        return result;
    }
    if (!q->head || !q->tail || !q->ids || q->capacity != NPU_COLD_PAGE_IDS ||
        ((uintptr_t)q->head & 1) || ((uintptr_t)q->tail & 1) || ((uintptr_t)q->ids & 1)) {
        result.page = fail(s, NPU_COLD_PAGE_CORRUPT);
        return result;
    }
    head = *q->head;
    tail = *q->tail;
    if (head >= NPU_COLD_PAGE_IDS || tail >= NPU_COLD_PAGE_IDS) {
        result.page = fail(s, NPU_COLD_PAGE_CORRUPT);
        return result;
    }
    id = q->ids[head];
    result.page = npu_cold_page_take(s, p, epoch, head, tail, id);
    if (!result.page.committed)
        return result;

    /* Retain the private claim even when the native snapshot can no longer be
     * published. Never reset either cursor or give the claimed ID back. */
    if (*q->head != head || *q->tail != tail || q->ids[head] != id) {
        npu_cold_page_fault(s);
        result.page.status = NPU_COLD_PAGE_CORRUPT;
        return result;
    }
    __atomic_thread_fence(__ATOMIC_RELEASE);
    *q->head = (uint16_t)result.page.next_head;
    __atomic_thread_fence(__ATOMIC_SEQ_CST);
    if (*q->head != result.page.next_head) {
        npu_cold_page_fault(s);
        result.page.status = NPU_COLD_PAGE_CORRUPT;
        return result;
    }
    result.published = 1;
    if (faulted(s))
        result.page.status = NPU_COLD_PAGE_FAULT;
    return result;
}

struct npu_cold_page_result npu_cold_page_take(
    struct npu_cold_page_state *s, const struct npu_cold_page_plan *p,
    uint32_t epoch, uint32_t head, uint32_t tail, uint32_t id)
{
    struct npu_cold_page_result result = {NPU_COLD_PAGE_ARGUMENT, UINT32_MAX, 0, UINT32_MAX, 0};
    uint32_t i, owned = 0, next, bit;

    if (!s || !p)
        return result;
    if (__atomic_load_n(&s->magic, __ATOMIC_ACQUIRE) != NPU_COLD_PAGE_MAGIC || faulted(s))
        return fail(s, NPU_COLD_PAGE_FAULT);
    if (!s->epoch)
        return fail(s, NPU_COLD_PAGE_CORRUPT);
    if (!epoch || epoch != s->epoch) {
        result.status = NPU_COLD_PAGE_STALE;
        return result;
    }
    if (!plan_valid(p) || s->packet_base != p->packet_base || s->packet_bytes != p->packet_bytes ||
        head >= NPU_COLD_PAGE_IDS || tail >= NPU_COLD_PAGE_IDS || s->head != head ||
        s->count > NPU_COLD_PAGE_IDS ||
        s->head != (s->count & (NPU_COLD_PAGE_IDS - 1)))
        return fail(s, NPU_COLD_PAGE_CORRUPT);
    for (i = 0; i < NPU_COLD_PAGE_WORDS; i++)
        owned += population(s->claimed[i]);
    if (owned != s->count)
        return fail(s, NPU_COLD_PAGE_CORRUPT);
    next = (head + 1) & (NPU_COLD_PAGE_IDS - 1);
    if (next == tail)
        return fail(s, NPU_COLD_PAGE_EMPTY);
    if (id >= NPU_COLD_PAGE_IDS)
        return fail(s, NPU_COLD_PAGE_ID);
    bit = 1u << (id & 31);
    if (s->claimed[id >> 5] & bit)
        return fail(s, NPU_COLD_PAGE_DUPLICATE);
    if (faulted(s))
        return fail(s, NPU_COLD_PAGE_FAULT);

    /* Claim before native head publication. An interrupted caller retains this
     * record instead of letting another setup retry reuse the same page. */
    s->claimed[id >> 5] |= bit;
    s->head = next;
    s->count++;
    __atomic_thread_fence(__ATOMIC_RELEASE);
    result.id = id;
    result.address = p->packet_base + id * NPU_COLD_PAGE_BYTES;
    result.next_head = next;
    result.committed = 1;
    result.status = faulted(s) ? NPU_COLD_PAGE_FAULT : NPU_COLD_PAGE_OK;
    return result;
}
